      ap_s_rideF: "Front ride height",
      ap_h_rideF: "Lower means more floor downforce, until the floor hits the track and the downforce collapses.",
      ap_s_rideR: "Rear ride height",
      ap_h_rideR: "A higher rear makes more rake: extra floor downforce and a more pointed front end.",
      ap_s_springF: "Front springs",
