      ap_tr_lights: "Start lights",
      ap_trd_lights: "Five red lights, then they go out. Press the moment they do, without jumping the start.",
      ap_tr_catch: "Catch the balls",
      ap_trd_catch: "Balls fall faster and faster. Move the catcher with the mouse, your finger or the arrow keys.",
      ap_tr_tracking: "Hold the line",
      ap_trd_tracking: "A zone drifts left and right and slowly narrows. Keep your marker inside it for 25 seconds.",
      ap_tr_throttle: "Throttle feel",
      ap_trd_throttle: "Hold to press the pedal, release to lift. Keep the pedal inside the moving green window.",
      ap_tr_brake: "Braking point",
      ap_trd_brake: "The car races toward the braking board. Press at the exact moment its nose reaches it.",
      ap_tr_rhythm: "Endurance rhythm",
      ap_trd_rhythm: "Alternate left and right as fast and as evenly as you can for 18 seconds, like the gym.",
      ap_tr_pit: "Pit stop crew",
      ap_trd_pit: "Tap the lit wheel nut, twelve times, as the clock runs and alarms flash. Mistakes cost time.",
      ap_tg_quit: "Leave the session? The energy and money are already spent.",
      ap_tg_score: "Session score",
      ap_tg_nogain: "Too short or too weak to teach the driver anything.",
      ap_tg_lights_title: "Start",
      ap_tg_lights_ready: "Get ready…",
      ap_tg_lights_hint: "Click, tap or press Space when the lights go out",
      ap_tg_jump: "Jump start!",
      ap_tg_catch_hint: "Move: mouse, finger, ← →",
      ap_tg_track_hint: "Move: mouse, finger, ← →",
      ap_tg_throttle_hint: "Hold: mouse, finger or Space",
      ap_tg_brake_title: "Braking point",
      ap_tg_brake_hint: "Click, tap or Space when the nose reaches the board",
      ap_tg_brake_late: "Too late!",
      ap_tg_rhythm_hint: "Alternate ← → (or tap the sides)",
      ap_tg_pit_hint: "Tap the lit nut (or Q E A D)",
      ap_tr_reaction: "Start lights",
      ap_trd_reaction: "Five red lights, then they go out. Press the moment they do. Your average reaction time is compared with the reaction time of your pilot's current skill: within a quarter of it each way, a result equal to it gives nothing, a quarter quicker gives a whole skill point and a quarter slower takes one. A jump start or a missed press counts as exactly that time.",
      ap_tr_reflexes: "Falling ball",
      ap_trd_reflexes: "A ball falls down the middle of the screen. Click or press Space the moment it is exactly on the line. Eight balls; your average distance from the centre counts. How close you must be depends on your Reflexes skill: easy at skill 1, strictest at skill 100. Dead centre is 100%, the edge of the allowed distance 1%; further out is negative, down to -100%.",
      ap_tr_pace: "Catch the balls",
      ap_trd_pace: "Catch the falling balls with the basket. The grip meter rises 10% for every catch and falls 10% for every miss. Your catch rate counts. How many you may miss depends on your Pace skill: a lot at skill 1, only a few at skill 100.",
      ap_tr_braking: "Braking point",
      ap_trd_braking: "The car races toward the braking board. Press at the exact moment its nose reaches it. Six runs; your average distance error counts.",
      ap_tr_cornering: "Bends",
      ap_trd_cornering: "Keep the car on the green line through six bends; it gets faster towards the end. Click the left or right side of the screen, or press ← →, to turn the wheel one notch; it stays turned until you click back. As a bend comes, judge how many clicks it needs. Your average distance from the line counts.",
      ap_tr_traction: "Throttle on corner exit",
      ap_trd_traction: "Hold to press the pedal, release to lift. Follow the green window, which also shows what comes next. Your average distance from it counts.",
      ap_tr_consistency: "Time on target",
      ap_trd_consistency: "Start the clock and stop it as close as you can to the target time, a random 1.5 to 3 seconds each game; the bar is only visible at the start. Ten tries and only your best stop counts. How close you must be depends on your Consistency: a window of 1 second at skill 1 down to 0.5 seconds at skill 100. A dead-on stop is 100%, the edge of the window 1%; a small miss outside it costs 20%, a whole window further out costs 100%.",
      ap_tr_focus: "Hold the line",
      ap_trd_focus: "Keep your marker under the moving zone for 22 seconds: move it with ← → or by holding the left or right side of the screen. Now and then the circle at the top lights up: tap it or press Space before it goes out, without having to leave the zone. Missing it costs you.",
      ap_tr_composure: "Catch the slide",
      ap_trd_composure: "The car suddenly steps out. Hold ← → or the left or right side of the screen to turn the nose that way: if the nose swings right, hold left to bring it back, and let go once it is straight. Six slides; your average time to settle counts.",
      ap_tr_tyreCare: "Tyre temperature",
      ap_trd_tyreCare: "Heat drifts the tyre temperature around. Warm it (upper half or ▲) or cool it (lower half or ▼) and keep it in the green band for 22 seconds. Time spent outside the band counts.",
      ap_tr_wet: "Braking in the rain",
      ap_trd_wet: "Rain changes how far the car slides. Five practice stops in different rainfall show where it stops; on the sixth you must stop exactly at the board. Only the sixth counts.",
      ap_tr_fitness: "One-minute endurance",
      ap_trd_fitness: "Tap continuously for 60 seconds. Your average tap rate over the whole minute counts, so starting too fast and tiring out costs you. The higher your Fitness, the faster you must tap to earn points.",
      ap_tr_feedback: "Setup feel",
      ap_trd_feedback: "Find the hidden setup. Set the sliders and run: you get a lap time and an arrow for each slider. An arrow tells you whether to go higher or lower, and your earlier tries stay listed under each slider. The accuracy of your last run counts.",
      ap_tg_rf_hint: "Click or press Space when the ball is on the line",
      ap_tg_grip: "Grip",
      ap_tg_corner_hint: "Click left or right of the screen, or ← →, to turn the wheel",
