      ap_trd_crew_wheel: "Tap the lit wheel nut to take it off, one by one in the star pattern, until the wheel is bare. Then put every nut back on in the same order. Wrong taps cost points, and with more skill there are more nuts. Everything must be done before the five seconds run out. Six rounds.",
