      ap_trd_staff_doctor: "Дръж три жизнени показателя в зелената зона. Докосни лявата половина на лента, за да я намалиш, и дясната, за да я повишиш. Шест рунда по седем секунди.",
      ap_trd_staff_coach: "Показани са две графики на обиколката. Кликни точката, в която пилотът е загубил най-много време спрямо еталона. Шест рунда.",
      ap_trd_staff_engineer: "Един от четири уреда става червен. Кликни го и избери правилното радиосъобщение. Колкото по-бързо и вярно, толкова по-добре. Шест рунда.",
      ap_trd_staff_strategist: "Показан е износът на комплект гуми за първите обиколки. Кликни обиколката, в която ще стигне линията на срива. Шест рунда.",
      ap_trd_staff_meteorologist: "Дъждовен радар се показва за миг. След това задай каква част от района е била под дъжд и потвърди. Шест рунда.",
      ap_trd_staff_mechanic: "Частите на колата се показват една след друга само с цвят и пак се скриват. Запомни коя е най-износена и накрая кликни номера ѝ. Колкото по-близо е износването на избраната до най-голямото, толкова повече точки. С умението частите са повече, показват се по-кратко и цветовете им са по-близки. Шест рунда.",
      ap_trd_staff_scout: "Показанията на четирима таланти трептят. Прецени кой е най-добър общо и го кликни. Шест рунда.",
      ap_trd_staff_manager: "Спонсорът има скрита граница между 0 и 100. Ти избутваш зелената си оферта отляво, а той червената си лента отдясно. Задай предложението и натисни „Предложи“: с всеки опит спонсорът се приближава към истинската си граница, а при последния опит я достига. Натисни „Съгласен съм“, когато искаш да запазиш последното си предложение. Точно в границата е 100%, по-малко плаща пропорционално. Ако предложението мине границата, рундът свършва веднага и показва колко на минус си. С по-високо умение опитите са по-малко. Клавиатура: ← → за местене, Enter за предложение, интервал за съгласие. Шест рунда.",
