      ap_trd_traction: "Задръж, за да натиснеш педала, пусни, за да го отпуснеш. Следвай зеления прозорец, който показва и какво идва след това. Брои се средното ти отклонение от него.",
      ap_tr_consistency: "Време до целта",
      ap_trd_consistency: "Пусни часовника и го спри възможно най-близо до целевото време, произволно от 1,5 до 3 секунди за всяка игра; лентата се вижда само в началото. Десет опита, брои се само най-доброто ти спиране. Колко близо трябва да си зависи от Постоянството ти: прозорец от 1 секунда при ниво 1 до 0,5 секунди при ниво 100. Точно попадение е 100%, краят на прозореца 1%; малко извън него струва 20%, цял прозорец по-нататък струва 100%.",
      ap_tr_focus: "Дръж линията",
      ap_trd_focus: "Дръж маркера под движещата се зона 22 секунди: движи го с ← → или като държиш лявата или дясната страна на екрана. От време на време горният кръг светва: докосни го или натисни интервал, преди да изгасне, без да е нужно да напускаш зоната. Пропуснеш ли го, губиш.",
      ap_tr_composure: "Спасяване от плъзгане",
      ap_trd_composure: "Колата внезапно се плъзга. Задръж ← → или лявата или дясната страна на екрана, за да завъртиш носа натам: ако носът отива надясно, задръж наляво, за да го върнеш, и пусни, щом се изправи. Шест плъзгания; брои се средното време до стабилизиране.",
      ap_tr_tyreCare: "Температура на гумата",
      ap_trd_tyreCare: "Топлината мести температурата на гумата. Загрявай я (горната половина или ▲) или я охлаждай (долната половина или ▼) и я дръж в зелената зона 22 секунди. Брои се времето извън зоната.",
      ap_tr_wet: "Спиране на дъжд",
      ap_trd_wet: "Дъждът променя колко се плъзга колата. Пет тренировъчни спирания при различен валеж показват къде спира; на шестото трябва да спреш точно при табелата. Брои се само шестото.",
      ap_tr_fitness: "Издръжливост за една минута",
      ap_trd_fitness: "Натискай без прекъсване 60 секунди. Брои се средното ти темпо през цялата минута, така че ако започнеш твърде бързо и се изтощиш, губиш. Колкото по-високо е умението ти Кондиция, толкова по-бързо трябва да натискаш, за да печелиш точки.",
      ap_tr_feedback: "Усет за настройките",
      ap_trd_feedback: "Намери скритите настройки. Нагласи плъзгачите и пусни: получаваш време на обиколка и стрелка за всеки плъзгач. Стрелката казва дали да вдигнеш или смъкнеш, а предишните ти опити остават под плъзгача. Брои се точността на последния опит.",
