      ap_tr_crew_repair: "Ремонт на инсталация",
      ap_tr_crew_release: "Безопасно пускане в питлейна",
      ap_trd_crew_wheel: "Докосвай светещата гайка, за да я свалиш – една по една по звезда, докато колелото остане без гайки. После върни всички гайки в същия ред. Грешните докосвания струват точки, а с умението гайките стават повече. Всичко трябва да е готово преди да изтекат петте секунди. Шест рунда.",
      ap_trd_crew_jack: "Изтегли жълтия лост докрай надолу и го върни нагоре, за да помпаш крика. Задръж налягането в зелената зона 1,8 секунди без прекъсване; прекаленото помпане я надхвърля. С клавиатура: натискай и отпускай стрелка надолу за всеки ход. Шест рунда по пет секунди.",
      ap_trd_crew_repair: "Прокарай проводника от A до B през всички чупки на канала. Преките пътища и излизането от канала носят грешки. С клавиатура: интервал започва от A, а стрелките водят проводника. Шест рунда по пет секунди.",
      ap_trd_crew_release: "Следи движещите се коли в питлейна и четиримата механици. Когато всички са готови, натисни твоята червена кола при свободен прозорец; ранното пускане или пускането в трафика проваля рунда. С клавиатура: интервал. Шест рунда по пет секунди.",
      ap_crew_drill_round: "Рунд {n} / {total}",
      ap_crew_drill_skills: "Развива петте умения; по-голямата тежест означава повече развитие.",
      ap_err_car_limit: "Отборът се състезава с две коли и вече имаш и двете.",
      ap_err_member: "Този член на екипа не е наличен.",
      ap_err_occupied: "Тази позиция вече е заета.",
      ap_watch_car: "Гледай тази кола",
      ap_team_cars: "Двете ти коли",
      ap_team_cars_hint: "И двете коли участват заедно във всяка сесия от уикенда и в състезанието. Кликни пилот, за да гледаш колата му и да й даваш команди: всеки има собствени настройки, гуми, питстопове и питстоп екип.",
      ap_next_session: "Следва",
      ap_race_both_cars: "И двете коли трябва да са на една и съща стъпка от уикенда.",
      ap_stop_short: "Питстоп",
