      ap_strategy_hint: "Ein Plan für {n} Runden aus deinen Trainingsdaten, auf etwa ±{e}% genau. Der Buchstabe ist die Reifenmischung, die Zahl die Runden auf diesem Satz.",
      ap_strategy_need: "Fahre im Training mindestens zwei Runden auf einer Mischung, um einen Plan zu bekommen.",
      ap_lab_zones_none: "Ohne Chefmechaniker gibt es keine Farbzonen und keine Erfolgschance: Du musst raten, wie weit du gehen kannst.",
      ap_role_doctor: "Teamarzt",
      ap_role_coach: "Fahrertrainer",
      ap_role_engineer: "Renningenieur",
      ap_role_strategist: "Stratege",
      ap_role_meteorologist: "Meteorologe",
      ap_role_mechanic: "Chefmechaniker",
      ap_role_scout: "Scout",
      ap_role_manager: "Manager",
      ap_role_doctor_does: "Verkürzt die Zeit, die Fahrer, Crews und Spezialisten brauchen, um ihre Energie zu regenerieren.",
      ap_role_coach_does: "Fügt jeder Fahrertrainingseinheit Punkte hinzu: Ein schlechtes Ergebnis kostet weniger, ein gutes bringt mehr.",
      ap_role_engineer_does: "Macht die vorgeschlagenen Setup-Bereiche enger, sodass der Rat präziser wird.",
      ap_role_strategist_does: "Liefert die Reifenprognose und vor dem Rennen eine Reifenstrategie aus den Daten deiner Trainings.",
      ap_role_meteorologist_does: "Liefert die Wettervorhersage. Je besser, desto enger die Regenchance-Bereiche; ab Stufe 50 gibt es auch Kurzfristvorhersagen. Ohne Meteorologen gibt es gar keine Vorhersage.",
      ap_role_mechanic_does: "Färbt die Forschungsregler: Grün ist sicher, Rot ist riskant. Je besser, desto näher liegen die Farben an der Wahrheit. Ohne ihn musst du raten.",
      ap_role_scout_does: "Findet Fahrer auf dem Markt. Seine Stufe ist das höchste Potenzial der auffindbaren Fahrer. Ohne Scout tauchen nur die schwächsten auf.",
      ap_role_manager_does: "Verhandelt mit Sponsoren: Jedes Angebot zahlt um den Prozentwert der Manager-Stufe mehr.",
      ap_fx_doctor: "Die Erholungszeit der Energie ist {n}% kürzer.",
      ap_fx_coach: "+{n} Punkte auf jede Fahrertrainingseinheit.",
      ap_fx_engineer: "Setup-Vorschläge sind {n}% enger.",
      ap_fx_strategist: "Reifenprognosen sind auf etwa ±{n}% genau.",
      ap_fx_meteorologist: "Regenchancen werden innerhalb von ±{n} Punkten angezeigt.",
      ap_fx_mechanic: "Die Forschungszonen sind zu {n}% genau.",
      ap_fx_scout: "Findet Fahrer mit einem Potenzial von bis zu {n}.",
      ap_fx_manager: "Sponsorenangebote zahlen {n}% mehr.",
      ap_fx0_doctor: "Ohne Arzt regeneriert die Energie im normalen Tempo.",
      ap_fx0_coach: "Ohne Trainer gibt das Training keine Extrapunkte.",
      ap_fx0_engineer: "Ohne Ingenieur haben die vorgeschlagenen Bereiche ihre Standardbreite.",
      ap_fx0_strategist: "Ohne Strategen gibt es keine Reifenprognose, keine Reifenempfehlung und keine Rennstrategie.",
      ap_fx0_meteorologist: "Ohne Meteorologen gibt es keine Wettervorhersage.",
      ap_fx0_mechanic: "Ohne Chefmechaniker haben die Forschungsregler keine Farbzonen.",
      ap_fx0_scout: "Ohne Scout findet man nur die schwächsten Fahrer (Potenzial bis 45).",
      ap_fx0_manager: "Ohne Manager zahlen Sponsoren die Standardsummen.",
      ap_tr_staff_doctor: "Pulsmonitor",
      ap_tr_staff_coach: "Rundenanalyse",
      ap_tr_staff_engineer: "Funksprüche",
      ap_tr_staff_strategist: "Boxenfenster",
      ap_tr_staff_meteorologist: "Radar lesen",
      ap_tr_staff_mechanic: "Verschleißprüfung",
      ap_tr_staff_scout: "Talentsuche",
      ap_tr_staff_manager: "Sponsorenverhandlung",
      ap_trd_staff_doctor: "Halte drei Vitalwerte in der grünen Zone. Tippe auf die linke Hälfte eines Balkens, um ihn zu senken, auf die rechte, um ihn zu erhöhen. Sechs Runden zu sieben Sekunden.",
      ap_trd_staff_coach: "Zwei Rundenverläufe werden gezeigt. Klicke die Stelle, an der der Fahrer gegenüber der Referenz die meiste Zeit verloren hat. Sechs Runden.",
      ap_trd_staff_engineer: "Eines von vier Instrumenten wird rot. Klicke es an und wähle den richtigen Funkspruch. Je schneller und richtiger, desto besser. Sechs Runden.",
      ap_trd_staff_strategist: "Der Verschleiß eines Reifensatzes ist für die ersten Runden eingezeichnet. Klicke die Runde, in der er die Abbruchlinie erreicht. Sechs Runden.",
      ap_trd_staff_meteorologist: "Ein Regenradar wird kurz gezeigt. Stelle dann ein, welcher Anteil des Gebiets Regen hatte, und bestätige. Sechs Runden.",
      ap_trd_staff_mechanic: "Die Teile des Autos erscheinen nacheinander nur als Farbe und verschwinden wieder. Merke dir das am stärksten verschlissene und klicke am Ende seine Nummer. Je näher der Verschleiß deiner Wahl am höchsten liegt, desto mehr Punkte. Mit mehr Können gibt es mehr Teile, sie sind kürzer zu sehen und die Farben liegen näher beieinander. Sechs Runden.",
      ap_trd_staff_scout: "Die Messwerte von vier Talenten flackern. Finde heraus, wer insgesamt der Beste ist, und klicke ihn an. Sechs Runden.",
      ap_trd_staff_manager: "Ein Sponsor hat ein verborgenes Limit zwischen 0 und 100. Du schiebst dein grünes Angebot von links, der Sponsor seinen roten Balken von rechts. Stelle dein Angebot ein und drücke Anbieten: Mit jedem Versuch rückt der Sponsor seinem echten Limit näher und beim letzten erreicht er es. Mit Abschluss behältst du jederzeit dein letztes Angebot. Genau das Limit sind 100 %, weniger zahlt anteilig. Geht ein Angebot über das Limit, endet die Runde sofort und zeigt, wie weit du im Minus bist. Mehr Können bedeutet weniger Versuche. Tastatur: ← → bewegen, Enter anbieten, Leertaste Abschluss. Sechs Runden.",
      ap_stg_v_pulse: "Puls",
