      ap_tr_lights: "Startampel",
      ap_trd_lights: "Fünf rote Lichter, dann gehen sie aus. Drück genau dann, ohne den Start zu verpatzen.",
      ap_tr_catch: "Bälle fangen",
      ap_trd_catch: "Die Bälle fallen immer schneller. Bewege den Fänger mit Maus, Finger oder Pfeiltasten.",
      ap_tr_tracking: "Linie halten",
      ap_trd_tracking: "Eine Zone driftet hin und her und wird langsam schmaler. Halte deine Markierung 25 Sekunden darin.",
      ap_tr_throttle: "Gasgefühl",
      ap_trd_throttle: "Halten drückt das Pedal, Loslassen lüpft es. Halte das Pedal im wandernden grünen Fenster.",
      ap_tr_brake: "Bremspunkt",
      ap_trd_brake: "Das Auto rast auf die Bremstafel zu. Drück genau, wenn die Nase sie erreicht.",
      ap_tr_rhythm: "Ausdauerrhythmus",
      ap_trd_rhythm: "Wechsle 18 Sekunden lang so schnell und gleichmäßig wie möglich zwischen links und rechts, wie im Fitnessstudio.",
      ap_tr_pit: "Boxencrew",
      ap_trd_pit: "Tippe zwölfmal auf die leuchtende Radmutter, während die Uhr läuft und Alarme blinken. Fehler kosten Zeit.",
      ap_tg_quit: "Sitzung verlassen? Energie und Geld sind bereits ausgegeben.",
      ap_tg_score: "Ergebnis der Einheit",
      ap_tg_nogain: "Zu kurz oder zu schwach, um dem Fahrer etwas beizubringen.",
      ap_tg_lights_title: "Start",
      ap_tg_lights_ready: "Mach dich bereit …",
      ap_tg_lights_hint: "Klicke, tippe oder drücke die Leertaste, wenn die Lichter ausgehen",
      ap_tg_jump: "Fehlstart!",
      ap_tg_catch_hint: "Bewegen: Maus, Finger, ← →",
      ap_tg_track_hint: "Bewegen: Maus, Finger, ← →",
      ap_tg_throttle_hint: "Halten: Maus, Finger oder Leertaste",
      ap_tg_brake_title: "Bremspunkt",
      ap_tg_brake_hint: "Klick, Tippen oder Leertaste, wenn die Nase die Tafel erreicht",
      ap_tg_brake_late: "Zu spät!",
      ap_tg_rhythm_hint: "Abwechselnd ← → (oder die Seiten antippen)",
      ap_tg_pit_hint: "Tippe auf die leuchtende Mutter (oder Q E A D)",
      ap_tr_reaction: "Startampel",
      ap_trd_reaction: "Fünf rote Lichter, dann gehen sie aus. Drücke genau dann. Deine durchschnittliche Reaktionszeit wird mit der Reaktionszeit der aktuellen Fähigkeit deines Fahrers verglichen: innerhalb eines Viertels davon in beide Richtungen bringt ein gleiches Ergebnis nichts, ein Viertel schneller bringt einen ganzen Fähigkeitspunkt, ein Viertel langsamer nimmt einen. Ein Fehlstart oder ein verpasster Druck zählt als genau diese Zeit.",
      ap_tr_reflexes: "Fallender Ball",
      ap_trd_reflexes: "Ein Ball fällt in der Mitte des Bildschirms. Klicke oder drücke die Leertaste genau in dem Moment, in dem er auf der Linie ist. Acht Bälle; dein durchschnittlicher Abstand zur Mitte zählt. Wie genau du sein musst, hängt von deinem Können bei Reflexen ab: leicht bei Wert 1, am strengsten bei Wert 100. Genau in der Mitte sind 100 %, der Rand des erlaubten Abstands 1 %; weiter weg ist negativ, bis -100 %.",
      ap_tr_pace: "Bälle fangen",
      ap_trd_pace: "Fange die fallenden Bälle mit dem Korb. Die Grip-Anzeige steigt bei jedem Fang um 10 % und fällt bei jedem verpassten Ball um 10 %. Deine Fangquote zählt. Wie viele du verpassen darfst, hängt von deinem Tempo ab: viele bei Wert 1, nur wenige bei Wert 100.",
      ap_tr_braking: "Bremspunkt",
      ap_trd_braking: "Das Auto rast auf die Bremstafel zu. Drücke genau dann, wenn die Nase sie erreicht. Sechs Läufe; dein durchschnittlicher Abstandsfehler zählt.",
      ap_tr_cornering: "Kurven",
      ap_trd_cornering: "Halte das Auto durch sechs Kurven auf der grünen Linie; zum Ende wird es schneller. Klicke auf die linke oder rechte Bildschirmseite oder drücke ← →, um das Lenkrad eine Stufe zu drehen; es bleibt eingeschlagen, bis du zurückklickst. Schätze vor jeder Kurve ein, wie viele Klicks nötig sind. Dein durchschnittlicher Abstand zur Linie zählt.",
      ap_tr_traction: "Gas beim Kurvenausgang",
      ap_trd_traction: "Halten, um das Pedal zu drücken, loslassen, um zu lupfen. Folge dem grünen Fenster, das auch zeigt, was kommt. Dein durchschnittlicher Abstand dazu zählt.",
      ap_tr_consistency: "Zeit auf den Punkt",
      ap_trd_consistency: "Starte die Uhr und stoppe sie so nah wie möglich an der Zielzeit, in jedem Spiel zufällig zwischen 1,5 und 3 Sekunden; der Balken ist nur am Anfang sichtbar. Zehn Versuche, nur der beste Stopp zählt. Wie genau du sein musst, hängt von deiner Konstanz ab: ein Fenster von 1 Sekunde bei Wert 1 bis 0,5 Sekunden bei Wert 100. Ein Volltreffer sind 100 %, der Rand des Fensters 1 %; knapp außerhalb kostet 20 %, ein ganzes Fenster weiter draußen 100 %.",
      ap_tr_focus: "Linie halten",
      ap_trd_focus: "Halte deine Markierung 22 Sekunden unter der beweglichen Zone: mit ← → oder indem du die linke bzw. rechte Bildschirmseite gedrückt hältst. Ab und zu leuchtet der Kreis oben auf: tippe darauf oder drücke die Leertaste, bevor er erlischt, ohne die Zone verlassen zu müssen. Verpasst du es, kostet das.",
      ap_tr_composure: "Ausbrecher abfangen",
      ap_trd_composure: "Das Auto bricht plötzlich aus. Halte ← → oder die linke bzw. rechte Bildschirmseite gedrückt, um die Nase dorthin zu drehen: schwenkt die Nase nach rechts, halte links, um sie zurückzuholen, und lass los, sobald sie gerade ist. Sechs Ausbrüche; deine durchschnittliche Zeit bis zur Beruhigung zählt.",
      ap_tr_tyreCare: "Reifentemperatur",
      ap_trd_tyreCare: "Hitze verschiebt die Reifentemperatur. Wärme sie (obere Hälfte oder ▲) oder kühle sie (untere Hälfte oder ▼) und halte sie 22 Sekunden im grünen Bereich. Die Zeit außerhalb zählt.",
      ap_tr_wet: "Bremsen im Regen",
      ap_trd_wet: "Regen verändert, wie weit das Auto rutscht. Fünf Übungsstopps bei unterschiedlichem Regen zeigen, wo es hält; beim sechsten musst du genau an der Tafel stehen. Nur der sechste zählt.",
      ap_tr_fitness: "Ausdauer eine Minute",
      ap_trd_fitness: "Tippe 60 Sekunden lang ohne Pause. Deine durchschnittliche Tippgeschwindigkeit über die ganze Minute zählt, wer zu schnell startet und ermüdet, verliert. Je höher deine Fitness, desto schneller musst du tippen, um Punkte zu verdienen.",
      ap_tr_feedback: "Gefühl fürs Setup",
      ap_trd_feedback: "Finde das versteckte Setup. Stelle die Regler ein und fahre: du erhältst eine Rundenzeit und einen Pfeil je Regler. Der Pfeil zeigt, ob du höher oder niedriger gehen sollst, und deine früheren Versuche bleiben unter dem Regler stehen. Die Genauigkeit des letzten Laufs zählt.",
      ap_tg_rf_hint: "Klicke oder drücke die Leertaste, wenn der Ball auf der Linie ist",
      ap_tg_grip: "Grip",
      ap_tg_corner_hint: "Links oder rechts auf den Bildschirm klicken oder ← →, um zu lenken",
      ap_tg_cons_goal: "Stopp bei {n} s",
      ap_tg_cons_start: "Klick oder Leertaste startet die Uhr",
