      ap_tg_fb_hint: "▲ höher, ▼ niedriger, ✓ richtig. Jeder Regler behält die ganze Skala, darunter stehen deine früheren Versuche mit ihren Pfeilen.",
      ap_tg_reference: "Nötig bei deinem Können",
