      ap_tg_taps_s: "Tipps/s",
      ap_training_hint: "Jede Fähigkeit hat ihr eigenes kleines Spiel. Dein Ergebnis wird mit deinem aktuellen Niveau verglichen: +10 % darüber bringen 0,1 auf die Fähigkeit, +100 % bringen 1, ein schlechteres Ergebnis nimmt dieselbe Menge weg. Es gibt keine Obergrenze. Training kostet Energie, kein Geld.",
