      ap_crew_market_hint: "Für jede Position gibt es drei Kandidaten, die wöchentlich wechseln. Eine neue Crew braucht sechs Sekunden und mehr; eine bis zum Limit trainierte Crew wechselt vier Reifen in etwas unter zwei Sekunden.",
