      ap_tr_crew_release: "Sichere Boxenausfahrt",
      ap_trd_crew_wheel: "Tippe nacheinander im Sternmuster auf die leuchtende Radmutter, um sie abzunehmen, bis das Rad frei ist. Setze dann alle Muttern in derselben Reihenfolge wieder auf. Fehltipper kosten Punkte, mit mehr Können gibt es mehr Muttern. Alles muss in fünf Sekunden fertig sein. Sechs Runden.",
      ap_trd_crew_jack: "Ziehe den gelben Hebel ganz nach unten und wieder nach oben, um zu pumpen. Halte den Druck 1,8 Sekunden ununterbrochen im grünen Bereich; zu viel Pumpen überschreitet ihn. Tastatur: Pfeil unten für jeden Hub drücken und loslassen. Sechs Runden zu je fünf Sekunden.",
      ap_trd_crew_repair: "Ziehe das Kabel von A nach B durch alle Ecken des Kanals. Abkürzungen und Verlassen des Kanals verursachen Fehler. Tastatur: Leertaste beginnt bei A, Pfeiltasten führen das Kabel. Sechs Runden zu je fünf Sekunden.",
      ap_trd_crew_release: "Beobachte den Verkehr und alle vier Mechaniker. Tippe auf dein rotes Auto, wenn alle bereit sind und eine Lücke frei ist. Zu frühes Freigeben oder Verkehr lässt die Runde scheitern. Tastatur: Leertaste. Sechs Runden zu je fünf Sekunden.",
      ap_crew_drill_round: "Runde {n} / {total}",
