      ap_specialists: "Especialistas",
      ap_specialists_hint: "Una persona por cada función trabaja para todo el equipo. Ficha de las ofertas semanales, entrénala en su propio juego y vigila su edad de jubilación: un especialista veterano es barato pero se va pronto; uno joven con mucho techo cuesta más.",
