      ap_strategy: "Estrategia de carrera",
      ap_strategy_hint: "Un plan para {n} vueltas con los datos de los entrenamientos, con precisión de ±{e}% aprox. La letra es el compuesto y el número, las vueltas con ese juego.",
      ap_strategy_need: "Da al menos dos vueltas con un compuesto en los entrenamientos para obtener un plan.",
      ap_lab_zones_none: "Sin jefe de mecánicos no hay zonas de color ni probabilidad: tienes que adivinar hasta dónde apretar.",
      ap_role_doctor: "Médico del equipo",
      ap_role_coach: "Entrenador de pilotos",
      ap_role_engineer: "Ingeniero de carrera",
      ap_role_strategist: "Estratega",
      ap_role_meteorologist: "Meteorólogo",
      ap_role_mechanic: "Jefe de mecánicos",
      ap_role_scout: "Ojeador",
      ap_role_manager: "Mánager",
      ap_role_doctor_does: "Acorta el tiempo que pilotos, equipos y especialistas necesitan para recuperar la energía.",
      ap_role_coach_does: "Suma puntos a cada sesión de entrenamiento de pilotos: un mal resultado pierde menos y uno bueno gana más.",
      ap_role_engineer_does: "Estrecha los rangos sugeridos del reglaje, así que el consejo es más preciso.",
      ap_role_strategist_does: "Da el pronóstico de neumáticos y, antes de la carrera, una estrategia hecha con los datos de tus entrenamientos.",
      ap_role_meteorologist_does: "Da el pronóstico del tiempo. Cuanto mejor sea, más estrechos son los rangos de probabilidad de lluvia; por encima del nivel 50 también da los de corto plazo. Sin meteorólogo no hay pronóstico.",
      ap_role_mechanic_does: "Colorea los deslizadores de investigación: verde es seguro, rojo es riesgo. Cuanto mejor, más se acercan los colores a la realidad. Sin él, hay que adivinar.",
      ap_role_scout_does: "Encuentra pilotos en el mercado. Su nivel es el mayor potencial de los pilotos que puede encontrar. Sin ojeador solo aparecen los más flojos.",
      ap_role_manager_does: "Negocia con los patrocinadores: cada oferta paga más según el porcentaje del nivel del mánager.",
      ap_fx_doctor: "El tiempo de recuperación de energía es un {n}% menor.",
      ap_fx_coach: "+{n} puntos en cada sesión de entrenamiento de pilotos.",
      ap_fx_engineer: "Las sugerencias de reglaje son un {n}% más estrechas.",
      ap_fx_strategist: "Los pronósticos de neumáticos tienen una precisión de ±{n}% aprox.",
      ap_fx_meteorologist: "La probabilidad de lluvia se muestra dentro de ±{n} puntos.",
      ap_fx_mechanic: "Las zonas de investigación son un {n}% precisas.",
      ap_fx_scout: "Encuentra pilotos con un potencial de hasta {n}.",
      ap_fx_manager: "Las ofertas de patrocinio pagan un {n}% más.",
      ap_fx0_doctor: "Sin médico la energía se recupera al ritmo normal.",
      ap_fx0_coach: "Sin entrenador, el entrenamiento no da puntos extra.",
      ap_fx0_engineer: "Sin ingeniero, los rangos sugeridos tienen su ancho estándar.",
      ap_fx0_strategist: "Sin estratega no hay pronóstico de neumáticos, ni recomendación de compuesto, ni estrategia de carrera.",
      ap_fx0_meteorologist: "Sin meteorólogo no hay pronóstico del tiempo.",
      ap_fx0_mechanic: "Sin jefe de mecánicos, los deslizadores de investigación no tienen zonas de color.",
      ap_fx0_scout: "Sin ojeador solo se encuentran los pilotos más flojos (potencial hasta 45).",
      ap_fx0_manager: "Sin mánager los patrocinadores pagan las sumas estándar.",
      ap_tr_staff_doctor: "Monitor de pulso",
      ap_tr_staff_coach: "Análisis de vuelta",
      ap_tr_staff_engineer: "Llamadas por radio",
      ap_tr_staff_strategist: "Ventana de boxes",
      ap_tr_staff_meteorologist: "Lectura de radar",
      ap_tr_staff_mechanic: "Inspección del desgaste",
      ap_tr_staff_scout: "Búsqueda de talento",
      ap_tr_staff_manager: "Negociación con patrocinador",
      ap_trd_staff_doctor: "Mantén tres constantes vitales en la zona verde. Toca la mitad izquierda de una barra para bajarla y la derecha para subirla. Seis rondas de siete segundos.",
      ap_trd_staff_coach: "Se muestran dos trazas de vuelta. Haz clic en el punto donde el piloto perdió más tiempo respecto a la referencia. Seis rondas.",
      ap_trd_staff_engineer: "Uno de cuatro indicadores se pone en rojo. Haz clic en él y elige la llamada por radio correcta. Cuanto más rápido y acertado, mejor. Seis rondas.",
      ap_trd_staff_strategist: "Se muestra el desgaste de un juego de neumáticos en las primeras vueltas. Haz clic en la vuelta en que llegará a la línea del precipicio. Seis rondas.",
      ap_trd_staff_meteorologist: "Se muestra un radar de lluvia un instante. Luego indica qué parte de la zona estaba lloviendo y confirma. Seis rondas.",
      ap_trd_staff_mechanic: "Las piezas del coche aparecen una tras otra solo por color y vuelven a ocultarse. Recuerda cuál era la más desgastada y haz clic en su número al final. Cuanto más cerca esté el desgaste de tu elección del máximo, más puntos. Con más habilidad hay más piezas, se ven menos tiempo y sus colores se parecen más. Seis rondas.",
      ap_trd_staff_scout: "Las lecturas de cuatro promesas parpadean. Averigua quién es el mejor en conjunto y haz clic en él. Seis rondas.",
      ap_trd_staff_manager: "Un patrocinador tiene un límite oculto entre 0 y 100. Tú empujas tu oferta verde desde la izquierda y él su barra roja desde la derecha. Ajusta tu oferta y pulsa Ofrecer: con cada intento el patrocinador se acerca a su límite real y en el último lo alcanza. Pulsa Cerrar trato para quedarte con tu última oferta cuando quieras. Acertar el límite es 100 %, menos paga proporcionalmente. Si una oferta supera el límite, la ronda termina al instante y muestra cuánto estás en negativo. Más habilidad significa menos intentos. Teclado: ← → para mover, Enter para ofrecer, Espacio para cerrar. Seis rondas.",
      ap_stg_v_pulse: "Pulso",
      ap_stg_v_hydration: "Hidratación",
