      ap_s_springR: "Muelles traseros",
      ap_h_springR: "Misma idea atrás; también cambia cómo se asienta el coche al acelerar.",
      ap_s_arbF: "Barra estabilizadora delantera",
      ap_h_arbF: "Más rígida traslada carga al neumático delantero exterior: más subviraje, respuesta más viva.",
      ap_s_arbR: "Barra estabilizadora trasera",
      ap_h_arbR: "Más rígida carga el neumático trasero exterior: más sobreviraje, trasera más viva al entrar.",
      ap_s_camberF: "Caída delantera",
      ap_h_camberF: "Más negativa agarra mejor en curva, pero desgasta el borde interior y calienta el neumático.",
      ap_s_camberR: "Caída trasera",
      ap_h_camberR: "El mismo equilibrio atrás; muy poca pierde agarre, demasiada desgasta el neumático.",
      ap_s_pressF: "Presión delantera",
