      ap_s_pressR: "Presión trasera",
      ap_h_pressR: "Los neumáticos traseros transmiten la potencia y se calientan antes; menos presión los mantiene más fríos.",
      ap_s_brakeBias: "Reparto de frenada",
      ap_h_brakeBias: "Parte de la frenada en el eje delantero. Muy adelante bloquea las delanteras, muy atrás desestabiliza la trasera.",
