      ap_k_fitness: "Forma física",
      ap_k_feedback: "Feedback técnico",
      ap_tr_lights: "Semáforo de salida",
      ap_trd_lights: "Cinco luces rojas y luego se apagan. Pulsa justo cuando lo hagan, sin salir antes de tiempo.",
      ap_tr_catch: "Atrapa las bolas",
      ap_trd_catch: "Las bolas caen cada vez más rápido. Mueve el receptor con el ratón, el dedo o las flechas.",
      ap_tr_tracking: "Mantén la línea",
      ap_trd_tracking: "Una zona se desplaza y se estrecha poco a poco. Mantén tu marcador dentro durante 25 segundos.",
      ap_tr_throttle: "Tacto del acelerador",
      ap_trd_throttle: "Mantén pulsado para pisar el pedal, suelta para levantarlo. Mantén el pedal en la ventana verde móvil.",
      ap_tr_brake: "Punto de frenada",
      ap_trd_brake: "El coche se lanza hacia el cartel de frenada. Pulsa justo cuando su morro lo alcance.",
      ap_tr_rhythm: "Ritmo de resistencia",
      ap_trd_rhythm: "Alterna izquierda y derecha lo más rápido y parejo posible durante 18 segundos, como en el gimnasio.",
      ap_tr_pit: "Equipo de boxes",
      ap_trd_pit: "Toca doce veces la tuerca iluminada mientras corre el reloj y parpadean las alarmas. Los errores cuestan tiempo.",
      ap_tg_quit: "¿Salir de la sesión? La energía y el dinero ya están gastados.",
      ap_tg_score: "Resultado de la sesión",
      ap_tg_nogain: "Demasiado corto o flojo para enseñar algo al piloto.",
      ap_tg_lights_title: "Salida",
      ap_tg_lights_ready: "Prepárate…",
      ap_tg_lights_hint: "Haz clic, toca o pulsa Espacio cuando se apaguen las luces",
      ap_tg_jump: "¡Salida en falso!",
      ap_tg_catch_hint: "Mover: ratón, dedo, ← →",
      ap_tg_track_hint: "Mover: ratón, dedo, ← →",
      ap_tg_throttle_hint: "Mantén: ratón, dedo o Espacio",
      ap_tg_brake_title: "Punto de frenada",
      ap_tg_brake_hint: "Clic, toque o Espacio cuando el morro llegue al cartel",
      ap_tg_brake_late: "¡Demasiado tarde!",
      ap_tg_rhythm_hint: "Alterna ← → (o toca los lados)",
      ap_tg_pit_hint: "Toca la tuerca iluminada (o Q E A D)",
      ap_tr_reaction: "Semáforo de salida",
      ap_trd_reaction: "Cinco luces rojas y luego se apagan. Pulsa justo cuando se apaguen. Tu tiempo de reacción medio se compara con el tiempo de reacción de la habilidad actual de tu piloto: dentro de un cuarto en cada dirección, un resultado igual no da nada, un cuarto más rápido da un punto entero de habilidad y un cuarto más lento quita uno. Una salida en falso o una pulsación perdida cuenta como exactamente ese tiempo.",
      ap_tr_reflexes: "Bola que cae",
      ap_trd_reflexes: "Una bola cae por el centro de la pantalla. Haz clic o pulsa Espacio justo cuando esté sobre la línea. Ocho bolas; cuenta tu distancia media al centro. Lo cerca que debes estar depende de tu habilidad en Reflejos: fácil con nivel 1, lo más estricto con nivel 100. El centro exacto es 100 %, el borde de la distancia permitida 1 %; más lejos es negativo, hasta -100 %.",
      ap_tr_pace: "Atrapar las bolas",
      ap_trd_pace: "Atrapa las bolas que caen con la cesta. El medidor de agarre sube un 10 % con cada bola atrapada y baja un 10 % con cada fallo. Cuenta tu porcentaje de aciertos. Cuántas puedes fallar depende de tu habilidad en Ritmo: muchas con nivel 1, pocas con nivel 100.",
      ap_tr_braking: "Punto de frenada",
      ap_trd_braking: "El coche corre hacia la señal de frenada. Pulsa en el momento exacto en que su morro la alcance. Seis intentos; cuenta tu error medio de distancia.",
      ap_tr_cornering: "Curvas",
      ap_trd_cornering: "Mantén el coche sobre la línea verde en seis curvas; al final va más rápido. Haz clic en el lado izquierdo o derecho de la pantalla, o pulsa ← →, para girar el volante un punto; se queda girado hasta que hagas clic en sentido contrario. Al acercarse una curva, calcula cuántos clics necesita. Cuenta tu distancia media a la línea.",
      ap_tr_traction: "Acelerador a la salida de curva",
      ap_trd_traction: "Mantén para pisar el pedal, suelta para levantar. Sigue la ventana verde, que también muestra lo que viene. Cuenta tu distancia media a ella.",
      ap_tr_consistency: "Tiempo exacto",
      ap_trd_consistency: "Pon en marcha el reloj y deténlo lo más cerca posible del tiempo objetivo, aleatorio entre 1,5 y 3 segundos en cada juego; la barra solo se ve al principio. Diez intentos y solo cuenta tu mejor parada. Lo cerca que debes estar depende de tu Constancia: una ventana de 1 segundo con nivel 1 hasta 0,5 segundos con nivel 100. Un acierto exacto es 100 %, el borde de la ventana 1 %; un poco fuera resta 20 %, una ventana entera más lejos resta 100 %.",
      ap_tr_focus: "Mantén la línea",
      ap_trd_focus: "Mantén tu marcador bajo la zona móvil durante 22 segundos: muévelo con ← → o manteniendo pulsado el lado izquierdo o derecho de la pantalla. De vez en cuando se enciende el círculo de arriba: tócalo o pulsa Espacio antes de que se apague, sin tener que salir de la zona. Si lo pierdes, te cuesta.",
      ap_tr_composure: "Controlar el derrape",
      ap_trd_composure: "El coche se desliza de repente. Mantén ← → o el lado izquierdo o derecho de la pantalla para girar el morro hacia allí: si el morro se va a la derecha, mantén la izquierda para devolverlo y suelta cuando esté recto. Seis derrapes; cuenta tu tiempo medio hasta estabilizarlo.",
      ap_tr_tyreCare: "Temperatura del neumático",
      ap_trd_tyreCare: "El calor desplaza la temperatura del neumático. Caliéntalo (mitad superior o ▲) o enfríalo (mitad inferior o ▼) y mantenlo en la franja verde durante 22 segundos. Cuenta el tiempo fuera de la franja.",
      ap_tr_wet: "Frenar bajo la lluvia",
      ap_trd_wet: "La lluvia cambia cuánto se desliza el coche. Cinco frenadas de práctica con distinta lluvia muestran dónde se detiene; en la sexta debes parar justo en la señal. Solo cuenta la sexta.",
      ap_tr_fitness: "Resistencia de un minuto",
      ap_trd_fitness: "Toca sin parar durante 60 segundos. Cuenta tu ritmo medio durante todo el minuto, así que empezar demasiado rápido y cansarte te perjudica. Cuanto mayor sea tu Forma física, más rápido debes tocar para ganar puntos.",
      ap_tr_feedback: "Sensaciones del reglaje",
      ap_trd_feedback: "Encuentra el reglaje oculto. Ajusta los deslizadores y sal: recibes un tiempo de vuelta y una flecha por deslizador. La flecha indica si subir o bajar y tus intentos anteriores quedan listados bajo cada deslizador. Cuenta la precisión de la última.",
      ap_tg_rf_hint: "Haz clic o pulsa Espacio cuando la bola esté sobre la línea",
      ap_tg_grip: "Agarre",
