      ap_role_mechanic: "Chef mécanicien",
      ap_role_scout: "Dépisteur",
      ap_role_manager: "Manager",
      ap_role_doctor_does: "Raccourcit le temps dont les pilotes, les équipes et les spécialistes ont besoin pour récupérer leur énergie.",
      ap_role_coach_does: "Ajoute des points à chaque séance d'entraînement des pilotes : un mauvais résultat fait perdre moins, un bon gagne plus.",
      ap_role_engineer_does: "Rétrécit les plages de réglage suggérées : le conseil devient plus précis.",
      ap_role_strategist_does: "Fournit la prévision des pneus et, avant la course, une stratégie bâtie sur les données de tes essais.",
      ap_role_meteorologist_does: "Fournit la météo. Plus il est bon, plus les fourchettes de risque de pluie sont étroites ; au-dessus du niveau 50, il donne aussi le court terme. Sans lui, aucune prévision.",
      ap_role_mechanic_does: "Colorie les curseurs de recherche : vert est sûr, rouge est risqué. Plus il est bon, plus les couleurs sont proches de la réalité. Sans lui, tu devines.",
      ap_role_scout_does: "Déniche des pilotes sur le marché. Son niveau est le potentiel maximal des pilotes trouvables. Sans dépisteur, seuls les plus faibles apparaissent.",
      ap_role_manager_does: "Négocie avec les sponsors : chaque offre paie davantage, du pourcentage du niveau du manager.",
