      ap_fx0_doctor: "Sans médecin, l'énergie se récupère au rythme normal.",
      ap_fx0_coach: "Sans entraîneur, l'entraînement ne donne aucun point supplémentaire.",
      ap_fx0_engineer: "Sans ingénieur, les plages suggérées gardent leur largeur standard.",
      ap_fx0_strategist: "Sans stratège, il n'y a ni prévision de pneus, ni conseil de gomme, ni stratégie de course.",
      ap_fx0_meteorologist: "Sans météorologue, il n'y a pas de prévision météo.",
      ap_fx0_mechanic: "Sans chef mécanicien, les curseurs de recherche n'ont pas de zones de couleur.",
      ap_fx0_scout: "Sans dépisteur, seuls les pilotes les plus faibles se trouvent (potentiel jusqu'à 45).",
      ap_fx0_manager: "Sans manager, les sponsors paient les sommes standard.",
      ap_tr_staff_doctor: "Moniteur de pouls",
      ap_tr_staff_coach: "Analyse du tour",
      ap_tr_staff_engineer: "Appels radio",
      ap_tr_staff_strategist: "Fenêtre d'arrêt",
      ap_tr_staff_meteorologist: "Lecture du radar",
      ap_tr_staff_mechanic: "Inspection de l'usure",
      ap_tr_staff_scout: "Détection de talents",
      ap_tr_staff_manager: "Négociation avec un sponsor",
      ap_trd_staff_doctor: "Garde trois constantes vitales dans la zone verte. Touche la moitié gauche d'une barre pour la baisser, la droite pour la monter. Six manches de sept secondes.",
      ap_trd_staff_coach: "Deux tracés de tour sont affichés. Clique à l'endroit où le pilote a perdu le plus de temps par rapport à la référence. Six manches.",
      ap_trd_staff_engineer: "L'un des quatre cadrans passe au rouge. Clique dessus puis choisis le bon message radio. Plus c'est rapide et juste, mieux c'est. Six manches.",
      ap_trd_staff_strategist: "L'usure d'un train de pneus est tracée pour les premiers tours. Clique le tour où elle atteindra la ligne de chute. Six manches.",
      ap_trd_staff_meteorologist: "Un radar de pluie s'affiche un instant. Indique ensuite la part de la zone sous la pluie et valide. Six manches.",
      ap_trd_staff_mechanic: "Les pièces de la voiture apparaissent l’une après l’autre, seulement par leur couleur, puis disparaissent. Retiens la plus usée et clique sur son numéro à la fin. Plus l’usure de ton choix est proche du maximum, plus tu marques de points. Avec la compétence, il y a plus de pièces, elles restent moins longtemps et leurs couleurs sont plus proches. Six manches.",
      ap_trd_staff_scout: "Les mesures de quatre espoirs clignotent. Trouve le meilleur dans l'ensemble et clique dessus. Six manches.",
      ap_trd_staff_manager: "Un sponsor a une limite cachée entre 0 et 100. Tu pousses ton offre verte depuis la gauche et lui sa barre rouge depuis la droite. Règle ton offre et appuie sur Proposer : à chaque essai le sponsor se rapproche de sa vraie limite et au dernier il l’atteint. Appuie sur Conclure pour garder ta dernière offre quand tu veux. Tomber pile sur la limite donne 100 %, moins paie proportionnellement. Si une offre dépasse la limite, la manche s’arrête aussitôt et montre à quel point tu es dans le négatif. Plus de compétence, moins d’essais. Clavier : ← → pour bouger, Entrée pour proposer, Espace pour conclure. Six manches.",
