      ap_tr_lights: "Feux de départ",
      ap_trd_lights: "Cinq feux rouges, puis ils s'éteignent. Appuie à cet instant précis, sans partir trop tôt.",
      ap_tr_catch: "Attrape les balles",
      ap_trd_catch: "Les balles tombent de plus en plus vite. Déplace le panier avec la souris, le doigt ou les flèches.",
      ap_tr_tracking: "Tiens la ligne",
      ap_trd_tracking: "Une zone dérive et se rétrécit lentement. Garde ton repère dedans pendant 25 secondes.",
      ap_tr_throttle: "Toucher de gaz",
      ap_trd_throttle: "Maintiens pour appuyer sur la pédale, relâche pour lever. Garde la pédale dans la fenêtre verte mobile.",
      ap_tr_brake: "Point de freinage",
      ap_trd_brake: "La voiture fonce vers le panneau de freinage. Appuie à l'instant où son nez l'atteint.",
      ap_tr_rhythm: "Rythme d'endurance",
      ap_trd_rhythm: "Alterne gauche et droite aussi vite et régulièrement que possible pendant 18 secondes, comme à la salle.",
      ap_tr_pit: "Équipe des stands",
      ap_trd_pit: "Touche douze fois l'écrou allumé pendant que le chrono tourne et que les alarmes clignotent. Les erreurs coûtent du temps.",
      ap_tg_quit: "Quitter la session ? L'énergie et l'argent sont déjà dépensés.",
      ap_tg_score: "Résultat de la séance",
      ap_tg_nogain: "Trop court ou trop faible pour apprendre quoi que ce soit au pilote.",
      ap_tg_lights_title: "Départ",
      ap_tg_lights_ready: "Prépare-toi…",
      ap_tg_lights_hint: "Clique, touche ou appuie sur Espace quand les feux s'éteignent",
      ap_tg_jump: "Faux départ !",
      ap_tg_catch_hint: "Déplacer : souris, doigt, ← →",
      ap_tg_track_hint: "Déplacer : souris, doigt, ← →",
      ap_tg_throttle_hint: "Maintenir : souris, doigt ou Espace",
      ap_tg_brake_title: "Point de freinage",
      ap_tg_brake_hint: "Clic, toucher ou Espace quand le nez atteint le panneau",
      ap_tg_brake_late: "Trop tard !",
      ap_tg_rhythm_hint: "Alterne ← → (ou touche les côtés)",
      ap_tg_pit_hint: "Touche l'écrou allumé (ou Q E A D)",
      ap_tr_reaction: "Feux de départ",
      ap_trd_reaction: "Cinq feux rouges, puis ils s'éteignent. Appuyez à l'instant où ils s'éteignent. Votre temps de réaction moyen est comparé au temps de réaction de la compétence actuelle du pilote : dans un quart de part et d'autre, un résultat égal ne donne rien, un quart plus rapide donne un point de compétence entier et un quart plus lent en retire un. Un faux départ ou un appui manqué compte pour exactement ce temps.",
      ap_tr_reflexes: "Balle qui tombe",
      ap_trd_reflexes: "Une balle tombe au milieu de l'écran. Cliquez ou appuyez sur Espace au moment exact où elle est sur la ligne. Huit balles ; votre distance moyenne au centre compte. La précision demandée dépend de votre compétence en Réflexes : facile au niveau 1, la plus stricte au niveau 100. Le centre exact vaut 100 %, le bord de la distance permise 1 % ; plus loin est négatif, jusqu'à -100 %.",
      ap_tr_pace: "Attraper les balles",
      ap_trd_pace: "Attrapez les balles qui tombent avec le panier. La jauge d'adhérence monte de 10 % à chaque balle attrapée et baisse de 10 % à chaque balle ratée. Votre taux de réussite compte. Le nombre de balles manquées permis dépend de votre compétence en Rythme : beaucoup au niveau 1, peu au niveau 100.",
      ap_tr_braking: "Point de freinage",
      ap_trd_braking: "La voiture fonce vers le panneau de freinage. Appuyez au moment exact où son nez l'atteint. Six essais ; votre erreur moyenne de distance compte.",
      ap_tr_cornering: "Virages",
      ap_trd_cornering: "Gardez la voiture sur la ligne verte dans six virages ; la fin est plus rapide. Cliquez sur le côté gauche ou droit de l'écran, ou appuyez sur ← →, pour tourner le volant d'un cran ; il reste braqué jusqu'à ce que vous cliquiez dans l'autre sens. À l'approche d'un virage, évaluez combien de clics il faut. Votre écart moyen à la ligne compte.",
      ap_tr_traction: "Gaz en sortie de virage",
      ap_trd_traction: "Maintenez pour appuyer sur la pédale, relâchez pour lever. Suivez la fenêtre verte, qui montre aussi la suite. Votre écart moyen à celle-ci compte.",
      ap_tr_consistency: "Temps exact",
      ap_trd_consistency: "Lancez le chronomètre et arrêtez-le au plus près du temps cible, tiré au hasard entre 1,5 et 3 secondes à chaque jeu ; la barre n'est visible qu'au début. Dix essais, seul votre meilleur arrêt compte. La précision demandée dépend de votre Constance : une fenêtre de 1 seconde au niveau 1 jusqu'à 0,5 seconde au niveau 100. Un arrêt parfait vaut 100 %, le bord de la fenêtre 1 % ; un peu en dehors coûte 20 %, une fenêtre entière plus loin coûte 100 %.",
      ap_tr_focus: "Tenir la ligne",
      ap_trd_focus: "Gardez votre marqueur sous la zone mobile pendant 22 secondes : déplacez-le avec ← → ou en maintenant le côté gauche ou droit de l'écran. De temps en temps, le cercle du haut s'allume : touchez-le ou appuyez sur Espace avant qu'il s'éteigne, sans devoir quitter la zone. Le manquer vous coûte.",
      ap_tr_composure: "Rattraper la glisse",
      ap_trd_composure: "La voiture décroche soudain. Maintenez ← → ou le côté gauche ou droit de l'écran pour tourner l'avant de ce côté : si l'avant part à droite, maintenez la gauche pour le ramener, et relâchez dès qu'il est droit. Six glissades ; le temps moyen pour stabiliser compte.",
      ap_tr_tyreCare: "Température du pneu",
      ap_trd_tyreCare: "La chaleur fait varier la température du pneu. Réchauffez-le (moitié haute ou ▲) ou refroidissez-le (moitié basse ou ▼) et gardez-le dans la zone verte pendant 22 secondes. Le temps passé en dehors compte.",
      ap_tr_wet: "Freiner sous la pluie",
      ap_trd_wet: "La pluie change la distance de glisse. Cinq arrêts d'essai sous des pluies différentes montrent où la voiture s'arrête ; au sixième vous devez vous arrêter exactement au panneau. Seul le sixième compte.",
      ap_tr_fitness: "Endurance d'une minute",
      ap_trd_fitness: "Tapez sans interruption pendant 60 secondes. Votre rythme moyen sur toute la minute compte : démarrer trop vite et s'épuiser coûte des points. Plus votre Forme est élevée, plus vous devez taper vite pour gagner des points.",
      ap_tr_feedback: "Ressenti du réglage",
      ap_trd_feedback: "Trouvez le réglage caché. Placez les curseurs et lancez : vous obtenez un temps au tour et une flèche par curseur. La flèche indique s'il faut monter ou descendre, et vos essais précédents restent listés sous chaque curseur. La précision du dernier essai compte.",
      ap_tg_rf_hint: "Cliquez ou appuyez sur Espace quand la balle est sur la ligne",
      ap_tg_grip: "Adhérence",
      ap_tg_corner_hint: "Cliquez à gauche ou à droite de l'écran, ou ← →, pour tourner",
      ap_tg_cons_goal: "Arrêt à {n} s",
