      ap_tg_focus_hint: "Déplacer : ← → ou maintenir le côté gauche ou droit · Signal : le cercle du haut ou Espace",
      ap_tg_slide_hint: "Maintenez ← → ou le côté gauche ou droit pour tourner l'avant de ce côté",
      ap_tg_tyre_hint: "Moitié haute ou ↑ pour chauffer, moitié basse ou ↓ pour refroidir",
