      ap_trd_staff_doctor: "3つのバイタルを緑のゾーンに保ちます。バーの左半分をタップで下げ、右半分で上げます。7秒×6ラウンド。",
      ap_trd_staff_coach: "2本のラップ波形が表示されます。基準に対してドライバーが最もタイムを失った地点をクリックしてください。6ラウンド。",
      ap_trd_staff_engineer: "4つのメーターのうち1つが赤くなります。それをクリックし、正しい無線コールを選びます。速く正確なほど高評価。6ラウンド。",
