      ap_trd_staff_mechanic: "車のパーツが色だけで1つずつ順に表示され、また隠れます。最も摩耗していたものを覚え、最後にその番号をクリックしてください。選んだ摩耗が最大に近いほど高得点です。スキルが上がるとパーツが増え、表示時間が短くなり、色が近くなります。6ラウンド。",
      ap_trd_staff_scout: "4人の候補の数値がちらつきます。総合で最も優れた1人を見極めてクリックしてください。6ラウンド。",
      ap_trd_staff_manager: "スポンサーには0〜100の間に隠れた上限があります。あなたは緑の提示額を左から、スポンサーは赤いバーを右から押し進めます。提示額を決めて「提示する」を押すと、試すたびにスポンサーが本当の上限に近づき、最後の試行で上限に達します。「合意する」でいつでも直前の提示額で確定できます。上限ぴったりなら100%、下回れば比例します。上限を超えるとラウンドはすぐ終わり、どれだけマイナスかが表示されます。スキルが高いほど試行回数は少なくなります。キーボード：←→で移動、Enterで提示、スペースで合意。6ラウンド。",
