      ap_tr_reaction: "スタートライト",
      ap_trd_reaction: "赤いライトが5つ点灯し、やがて消えます。消えた瞬間に押してください。平均反応時間は、パイロットの現在のスキルに応じた反応時間と比較されます。その前後4分の1の範囲で、同じ結果なら変化なし、4分の1速ければスキル1ポイント獲得、4分の1遅ければ1ポイント減少します。フライングや押し忘れはちょうどその時間として数えられます。",
      ap_tr_reflexes: "落ちるボール",
      ap_trd_reflexes: "ボールが画面の中央を落ちてきます。ちょうど線の上に来た瞬間にクリックまたはスペースキーを押してください。8球の中心からの平均のずれで評価されます。必要な精度は反射神経の能力しだいで、レベル1では易しく、レベル100では最も厳しくなります。ど真ん中で100%、許容距離の端で1%、それより外はマイナスで最大-100%です。",
      ap_tr_pace: "ボールキャッチ",
      ap_trd_pace: "落ちてくるボールをカゴで受けてください。キャッチするとグリップメーターが10%上がり、逃すと10%下がります。キャッチ率が評価されます。取りこぼせる数はペースの能力しだいで、レベル1では多く、レベル100では少なくなります。",
      ap_tr_braking: "ブレーキングポイント",
      ap_trd_braking: "車がブレーキボードに向かって走ります。車の先端がボードに届く瞬間に押してください。6回走り、距離の平均誤差が評価されます。",
      ap_tr_cornering: "コーナー",
      ap_trd_cornering: "6つのコーナーで緑のラインから外れないように走ります。後半ほど速くなります。画面の左側または右側をクリックするか ← → を押すとハンドルが1段階回り、逆側をクリックするまでそのままです。コーナーが近づいたら、何回クリックが必要か見極めてください。ラインからの平均のずれで評価されます。",
      ap_tr_traction: "コーナー出口のスロットル",
      ap_trd_traction: "押し続けるとペダルを踏み、離すと戻ります。次に来る動きも表示される緑の窓に合わせてください。平均のずれが評価されます。",
      ap_tr_consistency: "タイム合わせ",
      ap_trd_consistency: "時計を動かし、目標時間にできるだけ近づけて止めてください。目標は毎回のゲームで1.5〜3秒からランダムに決まります。バーは最初だけ見えます。10回挑戦し、いちばん良い1回だけが評価されます。必要な精度は安定性しだいで、レベル1では1秒、レベル100では0.5秒の範囲です。ぴったりで100%、範囲の端で1%。範囲の少し外は-20%、範囲1つ分さらに外は-100%です。",
      ap_tr_focus: "ラインキープ",
      ap_trd_focus: "22秒間、動くゾーンの下にマーカーを保ちます。← →、または画面の左右の端を長押しして動かします。ときどき上の円が光るので、消える前にタップするかスペースキーを押してください。ゾーンから外れる必要はありません。逃すと減点されます。",
      ap_tr_composure: "スライド回復",
      ap_trd_composure: "車が突然スライドします。← →、または画面の左右を長押しして、その方向に車首を向けてください。車首が右に振れたら左を押して戻し、まっすぐになったら離します。6回のスライドで、安定するまでの平均時間が評価されます。",
