      ap_tr_staff_manager: "Negociação com patrocinador",
      ap_trd_staff_doctor: "Mantenha três sinais vitais na zona verde. Toque na metade esquerda de uma barra para baixar e na direita para subir. Seis rodadas de sete segundos.",
