      ap_k_feedback: "Feedback técnico",
      ap_tr_lights: "Semáforo de largada",
      ap_trd_lights: "Cinco luzes vermelhas e depois elas apagam. Aperte no instante exato, sem queimar a largada.",
      ap_tr_catch: "Pegue as bolas",
      ap_trd_catch: "As bolas caem cada vez mais rápido. Mova o coletor com o mouse, o dedo ou as setas.",
      ap_tr_tracking: "Mantenha a linha",
      ap_trd_tracking: "Uma zona vai de um lado a outro e estreita aos poucos. Mantenha seu marcador dentro por 25 segundos.",
      ap_tr_throttle: "Sensibilidade do acelerador",
      ap_trd_throttle: "Segure para pisar o pedal, solte para aliviar. Mantenha o pedal na janela verde em movimento.",
      ap_tr_brake: "Ponto de frenagem",
      ap_trd_brake: "O carro corre rumo à placa de frenagem. Aperte no instante em que o bico a alcançar.",
      ap_tr_rhythm: "Ritmo de resistência",
      ap_trd_rhythm: "Alterne esquerda e direita o mais rápido e uniforme possível por 18 segundos, como na academia.",
      ap_tr_pit: "Equipe de box",
      ap_trd_pit: "Toque doze vezes na porca iluminada enquanto o relógio corre e os alarmes piscam. Erros custam tempo.",
      ap_tg_quit: "Sair da sessão? A energia e o dinheiro já foram gastos.",
      ap_tg_score: "Resultado da sessão",
      ap_tg_nogain: "Curto ou fraco demais para ensinar algo ao piloto.",
      ap_tg_lights_title: "Largada",
      ap_tg_lights_ready: "Prepare-se…",
      ap_tg_lights_hint: "Clique, toque ou aperte Espaço quando as luzes apagarem",
      ap_tg_jump: "Largada queimada!",
      ap_tg_catch_hint: "Mover: mouse, dedo, ← →",
      ap_tg_track_hint: "Mover: mouse, dedo, ← →",
      ap_tg_throttle_hint: "Segure: mouse, dedo ou Espaço",
      ap_tg_brake_title: "Ponto de frenagem",
      ap_tg_brake_hint: "Clique, toque ou Espaço quando o bico chegar à placa",
      ap_tg_brake_late: "Tarde demais!",
      ap_tg_rhythm_hint: "Alterne ← → (ou toque nos lados)",
      ap_tg_pit_hint: "Toque a porca iluminada (ou Q E A D)",
      ap_tr_reaction: "Luzes de largada",
      ap_trd_reaction: "Cinco luzes vermelhas e depois elas apagam. Aperte no instante em que apagarem. Seu tempo médio de reação é comparado ao tempo de reação da habilidade atual do piloto: dentro de um quarto para cada lado, um resultado igual não dá nada, um quarto mais rápido dá um ponto inteiro de habilidade e um quarto mais lento tira um. Uma largada queimada ou um toque perdido conta como exatamente esse tempo.",
      ap_tr_reflexes: "Bola que cai",
      ap_trd_reflexes: "Uma bola cai pelo meio da tela. Clique ou pressione Espaço no instante em que ela estiver na linha. Oito bolas; conta a sua distância média até o centro. A precisão exigida depende da sua habilidade em Reflexos: fácil no nível 1, mais rigorosa no nível 100. O centro exato é 100%, a borda da distância permitida 1%; mais longe é negativo, até -100%.",
      ap_tr_pace: "Pegar as bolas",
      ap_trd_pace: "Pegue as bolas que caem com a cesta. O medidor de aderência sobe 10% a cada bola pega e cai 10% a cada erro. Conta sua taxa de acertos. Quantas você pode perder depende da sua habilidade em Ritmo: muitas no nível 1, poucas no nível 100.",
      ap_tr_braking: "Ponto de frenagem",
      ap_trd_braking: "O carro corre até a placa de frenagem. Aperte no momento exato em que o bico chegar nela. Seis tentativas; conta seu erro médio de distância.",
      ap_tr_cornering: "Curvas",
      ap_trd_cornering: "Mantenha o carro na linha verde em seis curvas; no final é mais rápido. Clique no lado esquerdo ou direito da tela, ou pressione ← →, para girar o volante um ponto; ele fica girado até você clicar no sentido contrário. Ao se aproximar uma curva, calcule quantos cliques ela exige. Conta a sua distância média até a linha.",
      ap_tr_traction: "Acelerador na saída da curva",
      ap_trd_traction: "Segure para pisar no pedal, solte para aliviar. Siga a janela verde, que também mostra o que vem a seguir. Conta sua distância média dela.",
      ap_tr_consistency: "Tempo exato",
      ap_trd_consistency: "Inicie o relógio e pare o mais perto possível do tempo-alvo, sorteado entre 1,5 e 3 segundos a cada jogo; a barra só aparece no início. Dez tentativas e só conta a sua melhor parada. A precisão exigida depende da sua Constância: uma janela de 1 segundo no nível 1 até 0,5 segundo no nível 100. Acerto exato é 100%, a borda da janela 1%; um pouco fora custa 20%, uma janela inteira mais longe custa 100%.",
      ap_tr_focus: "Manter a linha",
      ap_trd_focus: "Mantenha o marcador sob a zona em movimento por 22 segundos: mova com ← → ou segurando o lado esquerdo ou direito da tela. De vez em quando o círculo de cima acende: toque nele ou pressione Espaço antes que apague, sem precisar sair da zona. Perder custa pontos.",
      ap_tr_composure: "Controlar a derrapagem",
      ap_trd_composure: "O carro escorrega de repente. Segure ← → ou o lado esquerdo ou direito da tela para virar a frente para lá: se a frente for para a direita, segure a esquerda para trazê-la de volta e solte quando estiver reta. Seis derrapagens; conta o tempo médio para estabilizar.",
      ap_tr_tyreCare: "Temperatura do pneu",
      ap_trd_tyreCare: "O calor muda a temperatura do pneu. Aqueça (metade de cima ou ▲) ou esfrie (metade de baixo ou ▼) e mantenha na faixa verde por 22 segundos. Conta o tempo fora da faixa.",
      ap_tr_wet: "Frear na chuva",
      ap_trd_wet: "A chuva muda o quanto o carro desliza. Cinco paradas de treino com chuvas diferentes mostram onde ele para; na sexta você precisa parar exatamente na placa. Só a sexta conta.",
      ap_tr_fitness: "Resistência de um minuto",
      ap_trd_fitness: "Toque sem parar por 60 segundos. Conta o seu ritmo médio durante todo o minuto, então começar rápido demais e cansar custa pontos. Quanto maior a sua Forma física, mais rápido você precisa tocar para ganhar pontos.",
      ap_tr_feedback: "Sensação do acerto",
      ap_trd_feedback: "Descubra o acerto escondido. Ajuste os controles e saia: você recebe um tempo de volta e uma seta para cada controle. A seta indica se deve subir ou descer e as tentativas anteriores ficam listadas sob cada controle. Conta a precisão da última.",
      ap_tg_rf_hint: "Clique ou pressione Espaço quando a bola estiver na linha",
      ap_tg_grip: "Aderência",
      ap_tg_corner_hint: "Clique à esquerda ou à direita da tela, ou ← →, para esterçar",
