      ap_role_meteorologist_does: "Даёт прогноз погоды. Чем он сильнее, тем уже диапазоны вероятности дождя; выше уровня 50 появляется и краткосрочный прогноз. Без метеоролога прогноза нет совсем.",
      ap_role_mechanic_does: "Раскрашивает ползунки исследований: зелёный — безопасно, красный — риск. Чем он сильнее, тем ближе цвета к правде. Без него приходится угадывать.",
      ap_role_scout_does: "Находит пилотов на рынке. Его уровень — максимальный потенциал находимых пилотов. Без скаута попадаются только самые слабые.",
      ap_role_manager_does: "Договаривается со спонсорами: каждое предложение платит больше на процент уровня менеджера.",
      ap_fx_doctor: "Время восстановления энергии короче на {n}%.",
      ap_fx_coach: "+{n} очка к каждой тренировке пилотов.",
      ap_fx_engineer: "Предложения по настройкам уже на {n}%.",
      ap_fx_strategist: "Прогнозы по шинам точны примерно до ±{n}%.",
      ap_fx_meteorologist: "Вероятность дождя показывается с разбросом ±{n} п.",
      ap_fx_mechanic: "Зоны исследований точны на {n}%.",
