      ap_fx0_scout: "Без скаута находятся только самые слабые пилоты (потенциал до 45).",
      ap_fx0_manager: "Без менеджера спонсоры платят стандартные суммы.",
      ap_tr_staff_doctor: "Монитор пульса",
      ap_tr_staff_coach: "Анализ круга",
      ap_tr_staff_engineer: "Радиосвязь",
      ap_tr_staff_strategist: "Окно питстопа",
      ap_tr_staff_meteorologist: "Чтение радара",
      ap_tr_staff_mechanic: "Осмотр износа",
      ap_tr_staff_scout: "Поиск талантов",
      ap_tr_staff_manager: "Переговоры со спонсором",
      ap_trd_staff_doctor: "Держите три показателя в зелёной зоне. Нажмите на левую половину полосы, чтобы снизить, на правую — чтобы повысить. Шесть раундов по семь секунд.",
      ap_trd_staff_coach: "Показаны две кривые круга. Нажмите на точку, где пилот потерял больше всего времени относительно эталона. Шесть раундов.",
      ap_trd_staff_engineer: "Один из четырёх приборов краснеет. Нажмите на него и выберите верное радиосообщение. Чем быстрее и точнее, тем лучше. Шесть раундов.",
      ap_trd_staff_strategist: "Показан износ комплекта шин за первые круги. Нажмите на круг, на котором он достигнет линии обрыва. Шесть раундов.",
      ap_trd_staff_meteorologist: "Радар дождя показывается на мгновение. Затем задайте, какая доля района была под дождём, и подтвердите. Шесть раундов.",
      ap_trd_staff_mechanic: "Детали машины по очереди показываются только цветом и снова скрываются. Запомни самую изношенную и в конце нажми её номер. Чем ближе износ выбранной к максимальному, тем больше очков. С ростом навыка деталей больше, они видны меньше, а цвета ближе. Шесть раундов.",
      ap_trd_staff_scout: "Показатели четырёх кандидатов мерцают. Определите лучшего в целом и нажмите на него. Шесть раундов.",
      ap_trd_staff_manager: "У спонсора есть скрытый предел от 0 до 100. Вы толкаете своё зелёное предложение слева, а он свою красную полосу — справа. Задайте предложение и нажмите «Предложить»: с каждой попыткой спонсор приближается к настоящему пределу, а на последней достигает его. Нажмите «Согласен», чтобы остановиться на последнем предложении в любой момент. Точно в предел — 100%, меньше платит пропорционально. Если предложение выходит за предел, раунд сразу заканчивается и показывает, насколько вы в минусе. Чем выше навык, тем меньше попыток. Клавиатура: ← → двигать, Enter предложить, пробел согласиться. Шесть раундов.",
