      ap_tg_brake_title: "Точка торможения",
      ap_tg_brake_hint: "Клик, касание или пробел, когда нос достигнет таблички",
      ap_tg_brake_late: "Слишком поздно!",
      ap_tg_rhythm_hint: "Чередуй ← → (или касайся сторон)",
      ap_tg_pit_hint: "Нажми на подсвеченную гайку (или Q E A D)",
      ap_tr_reaction: "Стартовые огни",
      ap_trd_reaction: "Пять красных огней, затем они гаснут. Нажми в момент, когда погаснут. Среднее время реакции сравнивается со временем реакции текущего навыка пилота: в пределах четверти от него в обе стороны результат, равный ему, ничего не даёт, на четверть быстрее даёт целое очко навыка, на четверть медленнее отнимает одно. Фальстарт или пропущенное нажатие считается как ровно это время.",
      ap_tr_reflexes: "Падающий мяч",
      ap_trd_reflexes: "Мяч падает посередине экрана. Кликни или нажми пробел в момент, когда он ровно на линии. Восемь мячей; считается среднее расстояние от центра. Нужная точность зависит от навыка Рефлексы: легко на уровне 1, строже всего на уровне 100. Ровно в центре 100%, край допустимого расстояния 1%; дальше минус, до -100%.",
      ap_tr_pace: "Лови мячи",
      ap_trd_pace: "Лови падающие мячи корзиной. Шкала сцепления растёт на 10% за каждый пойманный мяч и падает на 10% за каждый пропущенный. Считается доля пойманных. Сколько можно пропустить, зависит от навыка Темп: много на уровне 1, лишь несколько на уровне 100.",
      ap_tr_braking: "Точка торможения",
      ap_trd_braking: "Машина мчится к знаку торможения. Нажми в момент, когда её нос достигнет знака. Шесть заездов; считается средняя ошибка по расстоянию.",
      ap_tr_cornering: "Повороты",
      ap_trd_cornering: "Держи машину на зелёной линии в шести поворотах; к концу скорость растёт. Кликни слева или справа на экране или нажми ← →, чтобы повернуть руль на одно деление; он остаётся повёрнутым, пока не кликнешь в обратную сторону. Когда приближается поворот, прикинь, сколько кликов нужно. Считается среднее отклонение от линии.",
      ap_tr_traction: "Газ на выходе из поворота",
      ap_trd_traction: "Удерживай, чтобы нажать педаль, отпусти, чтобы сбросить. Следуй за зелёным окном, которое показывает и то, что будет дальше. Считается среднее отклонение от него.",
      ap_tr_consistency: "Точно по времени",
      ap_trd_consistency: "Запусти секундомер и останови как можно ближе к целевому времени, случайному от 1,5 до 3 секунд в каждой игре; полоса видна только в начале. Десять попыток, считается только лучшая остановка. Нужная точность зависит от Стабильности: окно в 1 секунду при уровне 1 и 0,5 секунды при уровне 100. Точное попадание это 100%, край окна 1%; чуть за его пределами стоит 20%, на целое окно дальше стоит 100%.",
      ap_tr_focus: "Держи линию",
      ap_trd_focus: "Держи маркер под движущейся зоной 22 секунды: двигай его ← → или удерживая левую или правую сторону экрана. Время от времени верхний круг загорается: коснись его или нажми пробел, пока он не погас, не покидая зоны. Пропуск стоит очков.",
      ap_tr_composure: "Поймать занос",
      ap_trd_composure: "Машину внезапно заносит. Удерживай ← → или левую или правую сторону экрана, чтобы повернуть нос туда: если нос уходит вправо, удерживай влево, чтобы вернуть его, и отпусти, когда он выровняется. Шесть заносов; считается среднее время до стабилизации.",
      ap_tr_tyreCare: "Температура шины",
      ap_trd_tyreCare: "Жар сдвигает температуру шины. Грей её (верхняя половина или ▲) или охлаждай (нижняя половина или ▼) и держи в зелёной зоне 22 секунды. Считается время вне зоны.",
      ap_tr_wet: "Торможение под дождём",
      ap_trd_wet: "Дождь меняет длину скольжения. Пять тренировочных остановок при разном дожде показывают, где машина встаёт; на шестой нужно встать точно у знака. Считается только шестая.",
      ap_tr_fitness: "Выносливость за минуту",
      ap_trd_fitness: "Нажимай без остановки 60 секунд. Считается средний темп за всю минуту, поэтому слишком быстрый старт и усталость стоят очков. Чем выше твоя Выносливость, тем быстрее нужно нажимать, чтобы получать очки.",
      ap_tr_feedback: "Чувство настроек",
      ap_trd_feedback: "Найди скрытые настройки. Установи ползунки и выезжай: получишь время круга и стрелку для каждого ползунка. Стрелка показывает, выше или ниже идти, а прошлые попытки остаются под каждым ползунком. Считается точность последнего заезда.",
