      ap_tr_reaction: "起步灯",
      ap_trd_reaction: "五盏红灯亮起后熄灭。熄灭的瞬间按下。你的平均反应时间会与车手当前技能对应的反应时间比较：以其四分之一为上下范围，与之相等不得分，快四分之一得整整1点技能，慢四分之一则扣1点。抢跑或漏按按恰好该时间计算。",
